<?php
namespace App\Http\Controllers\Pelanggan;
use App\Http\Controllers\Controller;use App\Http\Requests\StorePengajuanMobilRequest;use App\Models\{KendaraanPelanggan,PengajuanMobil};use App\Services\PengajuanMobilService;use Illuminate\Http\Request;use Throwable;
class PengajuanMobilController extends Controller { private function customer(Request $r):int{return (int)$r->user()->pelanggan()->value('id_pelanggan');} public function index(Request $r){$rows=PengajuanMobil::with(['inspeksi'])->where('id_pelanggan',$this->customer($r))->latest()->paginate(15);return view('pelanggan.pengajuan-mobil.index',compact('rows'));}public function create(Request $r){$vehicles=KendaraanPelanggan::where('id_pelanggan',$this->customer($r))->where('status','aktif')->orderBy('merk')->get();$targetCar=$r->filled('mobil')?\App\Models\Mobil::whereKey($r->integer('mobil'))->where('status','tersedia')->first():null;return view('pelanggan.pengajuan-mobil.create',compact('vehicles','targetCar'));}public function store(StorePengajuanMobilRequest $req,PengajuanMobilService $svc){try{$d=$req->validated();$p=$svc->create($this->customer($req),(int)$d['id_kendaraan_pelanggan'],(string)$d['harga_harapan'],$d['catatan']??null);if($req->filled('target_mobil'))$req->session()->put('trade_in.target_mobil',(int)$req->input('target_mobil'));return redirect()->route('pelanggan.pengajuan-mobil.show',$p)->with('success','Pengajuan berhasil dikirim.');}catch(Throwable $e){return back()->withInput()->withErrors($e->getMessage());}}public function show(Request $r,PengajuanMobil $pengajuan_mobil){abort_unless((int)$pengajuan_mobil->id_pelanggan===$this->customer($r),403);$pengajuan_mobil->load(['inspeksi.petugas','kendaraan']);return view('pelanggan.pengajuan-mobil.show',['submission'=>$pengajuan_mobil]);}public function decision(Request $r,PengajuanMobil $pengajuan_mobil,string $decision,PengajuanMobilService $svc){abort_unless((int)$pengajuan_mobil->id_pelanggan===$this->customer($r),403);abort_unless(in_array($decision,['disetujui','ditolak'],true),404);try{$svc->decision($pengajuan_mobil->id_pengajuan,$this->customer($r),$decision);return back()->with('success','Keputusan penawaran tersimpan.');}catch(Throwable $e){return back()->withErrors($e->getMessage());}}}
